import { SeedTsInferredAuthRefreshTokenClient } from "../../src/Client";
import { mockServerPool } from "../mock-server/MockServerPool";
import { mockInferredAuthScheme } from "./mockAuth";

describe("AuthClient", () => {
    test("getTokenWithRefreshToken", async () => {
        const server = mockServerPool.createServer();
        mockInferredAuthScheme(server);

        const client = new SeedTsInferredAuthRefreshTokenClient({
            maxRetries: 0,
            refreshToken: "my-refresh-token",
            grantType: "refresh_token",
            scope: "read",
            environment: server.baseUrl,
        });
        const rawRequestBody = { refresh_token: "my-refresh-token", grant_type: "refresh_token", scope: "read" };
        const rawResponseBody = {
            access_token: "my-access-token",
            expires_in: 3600,
            refresh_token: "my-refresh-token",
        };

        server
            .mockEndpoint()
            .post("/token")
            .jsonBody(rawRequestBody)
            .respondWith()
            .statusCode(200)
            .jsonBody(rawResponseBody)
            .build();

        const response = await client.auth.getTokenWithRefreshToken({
            refresh_token: "my-refresh-token",
            grant_type: "refresh_token",
            scope: "read",
        });
        expect(response).toEqual(rawResponseBody);
    });
});
